import { dist2 } from '../core/math.js';
import { G, R } from '../state.js';
import { sfx } from '../audio/audio.js';
import { biomeAt } from '../world/terrain.js';
import { puff } from '../world/sky.js';
import { BUILD_BY_ID } from '../data/buildings.js';
